import assert from 'node:assert/strict';
import { dlopen, FFIType } from 'bun:ffi';
import { benchMemoryStability } from '/home/ubuntu/.herdr/worktrees/mad-dom/herdr-plan-bun-native-runtime-07-integration/scripts/bench-ffi-gc.mjs';
import { memoryGate } from '/home/ubuntu/.herdr/worktrees/mad-dom/herdr-plan-bun-native-runtime-07-integration/scripts/bench-memory-gate.mjs';
import { memoryDigest } from '/home/ubuntu/.herdr/worktrees/mad-dom/herdr-plan-bun-native-runtime-07-integration/tests/bun/fixtures/ffi-memory-digest.mjs';

const lib = dlopen('/tmp/mad-dom-bun-coordinator-rss.so', {
  retain_native_mb: { args: [], returns: FFIType.u32 },
  release_native_mb: { args: [], returns: FFIType.u32 },
});
let retained = 0;
try {
  const series = await benchMemoryStability({ afterRound(_index, measured) {
    if (!measured) return;
    assert.equal(lib.symbols.retain_native_mb(), ++retained);
  } });
  const ffiEvidence = await memoryDigest();
  const result = memoryGate(series, ffiEvidence);
  console.log(JSON.stringify({ control: 'native-malloc-page-touched', bunVersion: Bun.version,
    bunRevision: Bun.revision, retainedBytes: retained * 1048576, series, ffiEvidence, result }, null, 2));
  assert.ok(result.rows.some(row => row.name.startsWith('memory_rss_') && row.status === 'FAIL'), 'RSS gate must detect retained native memory');
  assert.equal(result.rows.find(row => row.name === 'memory_lifecycle_counters').status, 'pass');
} finally {
  assert.equal(lib.symbols.release_native_mb(), retained);
  lib.close();
}
